ll dp[1 << 22];
vector<int> g[22];
void solve(int CASE)
{
    int n; cin >> n;
    fa(i, 0, n - 1)cin >> p[i];

    bool ok = 0;
    fa(i, 1, n - 1) {
        if (p[i] - p[i - 1] != 1) {
            ok = 1;
            break;
        }
    }
    if (!ok) {
        ll ans = 1;
        fa(i, 1, n)ans = ans * i % mod;
        cout << ans << endl;
