    }

    fa(i, 0, n - 1)fa(j, i + 1, n - 1) {
        if (p[i] > p[j]) {
            g[p[i] - 1].pb(p[j] - 1);
            deg[p[j] - 1]++;
        }
    }
    var Q = queue<int>();
    fa(i, 0, n - 1)if (!deg[i])Q.push(i);
    while (Q.size()) {
        int now = Q.front();
        Q.pop();
        for (int to : g[now]) {
            deg[to]--;
            need[to] |= (need[now] | (1 << now));
            if (!deg[to])Q.push(to);
        }
    }
    fa(i, 0, n - 1)if (deg[i]) {
        cout << 0 << endl;
        return;
    }
    dp[0] = 1;
    fa(st, 1, (1 << n) - 1) {
        fa(i, 0, n - 1)if (st & (1 << i)) {
            int nst = (st ^ (1 << i));
            if ((nst & need[i]) == need[i])
                dp[st] = (dp[st] + dp[nst]) % mod;
        }
    }
    cout << dp[(1 << n) - 1] * 2 % mod << endl;
    return;
}
